local mediaservice = medialib.load 'media'local function getYouTubeVP8(url, onSuccess, onError)	local id	if string.find(url, 'youtu.be/') then		id = string.Replace(url, 'https://', '')		id = string.Replace(id, 'http://', '')		id = string.Replace(id, 'www.', '')		id = string.Replace(id, 'youtu.be', '')		id = string.Replace(id, '/', '')	else		local params = string.ParseURL(url)		if (not params.v) then			onError('cannot parse url')			return		end		id = params.v	end	http.Fetch('http://www.youtube.com/get_video_info?video_id=' .. id:Trim() .. '&el=embedded&ps=default&eurl=&gl=US&hl=en', function(body, len, headers, code)		local x = string.Explode('&', body)		local t, g = {}, {}		for _, r in ipairs(x) do			local c = string.Explode('=', r)			t[c[1]] = c[2]		end		if (not t.url_encoded_fmt_stream_map) then			onError('no url_encoded_fmt_stream_map')			return		end		local streams = string.Explode(',', string.URLDecode(t.url_encoded_fmt_stream_map))		for _, dt in ipairs(streams) do			local x = string.Explode('&', dt)			local k = #g + 1			g[k] = {}			for _, r in ipairs(x) do				local c = string.Explode('=', r)				if c[1] and c[2] then					g[k][c[1]] = string.URLDecode(c[2])				end			end		end		for k, v in pairs(g) do			if v.url and v.type and string.find(v.type, 'video/webm') then				onSuccess(v.url:URLEncode())				return			end		end		onError('no vp8 source')	end, onError)endlocal WebmService = medialib.load("oop").class("Webm2Service", "HTMLService")WebmService.identifier = "webm2"function WebmService:parseUrl(url)	return {id = url}endfunction WebmService:isValidUrl(url)	return trueendlocal player_url = "https://superiorservers.co/medialib.html?id=%s"function WebmService:resolveUrl(url, callback)	local urlData = self:parseUrl(url)	local playerUrl = string.format(player_url, urlData.id)	callback(playerUrl, {start = urlData.start})endfunction WebmService:directQuery(url, callback)	callback(nil, {		title = url:match("([^/]+)$")	})endfunction ENT:OnPlay(media)endfunction ENT:GetSoundOrigin()	return selfendfunction ENT:Think()	local link = self:GetURL()	local lp = LocalPlayer()	local shouldplay = cvar.GetValue('media_enable') and (system.HasFocus() or (not cvar.GetValue('media_mute_when_unfocused'))) and (lp:EyePos():Distance(self:GetPos()) < 1024) and self:IsFrozen() and (not self:IsPaused()) and ((not lp.AfkTime) or lp.AfkTime < 300)	if IsValid(self.Media) and ((not link) or (not shouldplay)) then		self.Media:stop()		self.Media = nil		self.MediaURL = nil		self.Busy = nil	elseif shouldplay and ((not self.MediaURL) or (self.MediaURL ~= link)) and (not self.Busy) then		if IsValid(self.Media) then			self.Media:stop()			self.Media = nil			self.MediaURL = nil			self.Busy = nil		end		if (link ~= '') then			self.Busy = true			local service = mediaservice.guessService(link)			if service then				self.MediaURL = link				getYouTubeVP8(link, function(link)					print(link)					if IsValid(self) then						local mediaclip = WebmService:load(link, {use3D = true, ent3D = self:GetSoundOrigin()})						self:OnPlay(mediaclip)						mediaclip:setVolume(cvar.GetValue('media_volume') or 0.75)						--mediaclip:setQuality(cvar.GetValue('media_quality'))						if (self:GetTime() ~= 0) then							mediaclip:seek(CurTime() - self:GetStart())						end						mediaclip:play()						self.Media = mediaclip						self.Busy = nil					end				end, function(error)					print(error)					self.Busy = nil				end)			end		end	endend/*				if true or (self.ServiceType == "Audio") then					http.Fetch('https://www.saveoffline.com/process/?url=' .. link .. '&type=json', function(body)						local resp = util.JSONToTable(body)						PrintTable(resp)						local audio_url						if resp and resp.urls then							for k, v in ipairs(resp.urls) do								if v.label and string.find(v.label, 'webm') then									audio_url = v.id:URLEncode()									break								en